Lex["818"] = "atimazo {at-im-ad'-zo}|AV - dishonour 3, entreat shamefully 1, suffer shame 1, despise 1; 6|from 820||verb|INDENT0--<b>1)</b> to dishonour, insult, treat with contemptINDENT3-- <b>a)</b> whether in word, deed or thought<br /><BR /><hr />INDENT0--<b>Strong\'s Definition</b><br> ἀτιμάζω atim&#xE1;z&#x14D;, at-im-ad&#39;-zo; from Strong\'s <a href=\"strongs_greek.html?strongs=820&page=1\">G820</a>; to render infamous, i.e. (by implication) contemn or maltreat:&#8212;despise, dishonour, suffer shame, entreat shamefully.";
Lex["819"] = "atimia {at-ee-mee'-ah}|AV - dishonour 4, vile 1, shame 1, reproach 1; 7|from 820||noun feminine|INDENT0--<b>1)</b> dishonour, ignominy, disgrace<br /><BR /><hr />INDENT0--<b>Strong\'s Definition</b><br> ἀτιμία atim&#xED;a, at-ee-mee&#39;-ah; from Strong\'s <a href=\"strongs_greek.html?strongs=820&page=1\">G820</a>; infamy, i.e. (subjectively) comparative indignity, (objectively) disgrace:&#8212;dishonour, reproach, shame, vile.";
