Lex["4250"] = "prin {prin}|AV - before 11, before that 2, ere 1; 14|from 4253||adverb|INDENT0--<b>1)</b> before, formerly<br /><BR /><hr />INDENT0--<b>Strong\'s Definition</b><br> πρίν pr&#xED;n, prin; adverb from Strong\'s <a href=\"strongs_greek.html?strongs=4253&page=1\">G4253</a>; prior, sooner:&#8212;before (that), ere.";
